INSERT INTO public.celeb_professions (value,label,label_en,description,description_en,sort_order) VALUES
('leader','지도자','Leader','조직과 공동체가 나아갈 방향을 정하고 이끕니다.','A person who sets direction and leads an organization or community.',0),
('politician','정치인','Politician','공공의 문제를 다루고 정책을 결정합니다.','A person involved in public decision-making and policy.',1),
('commander','지휘관','Commander','군대나 집단의 작전을 세우고 지휘합니다.','A person who commands military or group operations.',2),
('entrepreneur','기업가','Entrepreneur','새로운 사업을 시작하고 조직을 키워 갑니다.','A person who builds and grows new businesses or organizations.',3),
('investor','투자자','Investor','자본을 어디에 맡길지 판단하고 기업과 자산의 가치를 살핍니다.','A person who allocates capital and evaluates businesses or assets.',4),
('scientist','과학자','Scientist','자연과 세계의 원리를 관찰하고 검증합니다.','A person who investigates and tests how the natural world works.',5),
('humanities_scholar','인문학자','Humanities Scholar','언어·역사·철학을 바탕으로 인간과 문화를 연구합니다.','A scholar who studies language, history, philosophy, and human culture.',6),
('social_scientist','사회과학자','Social Scientist','사회와 사람들의 행동, 관계를 연구합니다.','A person who studies society and human behavior or relationships.',7),
('director','감독','Director','영화와 영상 작품의 방향을 정하고 완성까지 이끕니다.','A person who leads the creative direction of film or video works.',8),
('musician','음악인','Musician','소리와 음악으로 자신의 작품을 만듭니다.','A person who creates works through sound and music.',9),
('visual_artist','미술인','Visual Artist','이미지와 조형 언어로 생각과 감정을 표현합니다.','A person who expresses ideas through visual and material language.',10),
('author','작가','Author','글을 쓰고 책과 이야기를 만듭니다.','A person who writes and creates books or stories.',11),
('actor','배우','Actor','작품 속 인물을 연기로 살아 있게 만듭니다.','A person who portrays characters through performance.',12),
('influencer','인플루엔서','Influencer','자신의 생각과 취향으로 대중의 관심과 문화를 움직입니다.','A person who influences public opinion and culture.',13),
('athlete','스포츠인','Athlete','스포츠 기술을 갈고닦으며 경기와 기록에 도전합니다.','A person who pursues achievement through sporting skill and competition.',14),
('other','기타','Other','기존 직군 하나로 대표 활동을 설명하기 어려운 인물입니다.','A figure whose primary role does not fit the existing professions.',15);
INSERT INTO public.profession_book_picks (profession,category,content_id,note,note_en,source_url,sort_order) VALUES
('leader','become','81992acc-4c81-42db-8f61-0719406a4ced','신뢰를 얻고 공동의 목표를 세우는 리더의 행동을 배우는 책.','Learn the practices of earning trust and leading toward a shared goal.','https://www.leadershipchallenge.com/five-practices/books',0),
('leader','become','4e880e7a-1071-4983-9608-0eb9fb663b3d','회의·피드백·업무 배분을 통해 팀의 성과를 높이는 방법을 배운다.','Learn how meetings, feedback and delegation improve a team’s output.','https://www.penguinrandomhouse.com/books/72467/high-output-management-by-andrew-s-grove-former-chairman-and-ceo-of-intel/',1),
('leader','about','772a5b82-e31b-423e-a8a7-883bd5e2ac12','링컨이 경쟁자들과 함께 나라를 이끌었던 과정을 통해 지도자의 일을 들여다본다.','See leadership through Lincoln’s work with his political rivals.','https://www.simonandschuster.com/books/Team-of-Rivals/Doris-Kearns-Goodwin/9780684824901',2),
('leader','about','ccef1591-482f-4db5-8bdf-bf5fd3e3a155','만델라의 삶을 따라 공동체를 이끄는 선택과 책임을 살펴본다.','Explore the choices and responsibilities of leadership through Mandela’s life.','https://www.hachettebookgroup.com/titles/nelson-mandela/long-walk-to-freedom/9780316548182/',3),
('politician','become','c38e78b8-1df8-4a4e-8ded-638f1ab32a69','권력을 맡는 사람에게 필요한 책임과 정치적 판단을 생각하게 한다.','Consider the responsibility and judgment required of those who exercise political power.','https://hackettpublishing.com/the-vocation-lectures',4),
('politician','become','df094f0f-db6b-458f-99bf-66ffdb45de30','권력의 획득과 유지라는 정치의 현실을 비판적으로 읽는 고전.','A classic for critically examining how political power is acquired and maintained.','https://www.penguinrandomhouse.com/books/531158/the-prince-by-niccolo-machiavelli/',5),
('politician','about','f1bfe4f8-502b-495b-84ee-416030ecb867','선거에서 국정 운영까지 정치인이 겪는 협상과 갈등을 회고록으로 읽는다.','Read a politician’s account of campaigning, governing, negotiation and conflict.','https://www.penguinrandomhouse.com/books/562882/a-promised-land-by-barack-obama/',6),
('politician','about','670fe23f-11e4-5df9-b9e0-2280077c8f43','정치인이 가치관을 정책과 공적 언어로 풀어내는 과정을 살펴본다.','See how a politician connects personal convictions with public policy.','https://www.penguinrandomhouse.com/books/123913/the-audacity-of-hope-by-barack-obama/',7),
('commander','become','0925e1cc-92c1-4b74-b691-f125bde6ccde','병력·정보·지형을 함께 고려하는 전략적 판단의 기초를 배운다.','Study strategic judgment through forces, intelligence and terrain.','https://www.penguinrandomhouse.com/books/600221/the-art-of-war-by-sun-tzu-translated-and-introduced-by-peter-harris/',8),
('commander','become','e4d868f1-a867-419c-a078-23bc5910697a','정치적 목표와 군사적 수단, 전장의 불확실성을 함께 생각하는 책.','Learn to connect political aims, military means and battlefield uncertainty.','https://www.penguinrandomhouse.com/books/28520/on-war-by-carl-von-clausewitz-translated-by-michael-howard-and-peter-paret-introduction-by-michael-howard/',9),
('commander','about','507d9781-5f91-437e-92e7-5036a3884cc2','명령을 내리는 지도 위에서 내려와 병사들이 실제로 겪는 전투를 본다.','Understand battle through the experience of the soldiers carrying out orders.','https://www.penguinrandomhouse.com/books/315430/the-face-of-battle-by-john-keegan/',10),
('commander','about','fbbfd924-24dd-4f05-88ed-3f6e61ae6ad5','이순신의 일기로 전쟁 중 지휘관의 판단과 책임, 일상을 살펴본다.','Explore a commander’s judgment, responsibilities and daily life through Yi Sun-sin’s wartime diary.','https://search.daum.net/search?w=bookpage&bookId=6154693&q=%EB%82%9C%EC%A4%91%EC%9D%BC%EA%B8%B0%28%EC%99%84%EC%97%AD%EB%B3%B8%29',11),
('entrepreneur','become','b5127bb9-d028-4bd0-858c-5e4577eadce6','고객의 반응으로 가설을 검증하며 사업을 시작하는 방법을 배운다.','Learn to start a business by testing assumptions with customer feedback.','https://www.penguinrandomhouse.com/books/210088/the-lean-startup-by-eric-ries/',12),
('entrepreneur','become','6e4ceff7-b652-412d-9fa0-cb26a659df2f','남을 따라가기보다 새로운 가치를 만드는 사업의 질문을 익힌다.','Learn the questions behind building a business that creates something new.','https://www.penguinrandomhouse.com/books/234730/zero-to-one-by-peter-thiel-with-blake-masters/9780804139304/',13),
('entrepreneur','about','eff1bb2b-2529-44f3-867a-4c9e60ccc3ef','나이키 창업의 자금난과 시행착오를 통해 기업가의 일상을 들여다본다.','See an entrepreneur’s working life through Nike’s early struggles and experiments.','https://www.simonandschuster.com/books/Shoe-Dog/Phil-Knight/9781501135910',14),
('entrepreneur','about','d6edaed5-7897-4649-a2f2-3475aed81f31','정답 없는 경영 위기에서 창업자가 맡는 결정과 책임을 읽는다.','Explore a founder’s decisions and responsibilities when management has no easy answers.','https://a16z.com/books/the-hard-thing-about-hard-things/',15),
('investor','become','c21ca51c-a7ab-4c8d-b842-46f3f7f6a682','가격과 가치를 구별하고 안전마진을 따지는 투자 원칙을 배운다.','Learn to distinguish price from value and reason about a margin of safety.','https://jasonzweig.com/books/the-intelligent-investor/',16),
('investor','become','a870ce31-9656-4417-8a24-e626303f7419','기업의 성장 가능성과 경영의 질을 조사하는 장기 투자 관점을 익힌다.','Develop a long-term approach to researching business quality and growth.','https://www.wiley-vch.de/en/areas-interest/finance-economics-law/common-stocks-and-uncommon-profits-and-other-writings-978-0-471-44550-0',17),
('investor','about','7f2ad4fe-5dc3-5460-9216-7d97e04c85c7','버핏의 생애와 의사결정을 통해 투자자의 일과 생활을 살펴본다.','Explore an investor’s work and life through Buffett’s biography.','https://www.penguinrandomhouse.com/books/162310/the-snowball-by-alice-schroeder/',18),
('investor','about','0bdfe5fa-05c7-58e9-b84c-283b202bdb18','헤지펀드의 역사와 운용자들의 선택을 통해 전문 투자자의 세계를 읽는다.','Discover professional investing through the history and decisions of hedge-fund managers.','https://www.penguinrandomhouse.com/books/301223/more-money-than-god-by-sebastian-mallaby/',19),
('scientist','become','4ef61dcd-c65e-4c0f-a479-68c9b916c0bd','연구 주제 선택과 동료 협업 등 과학자로 일하는 데 필요한 조언을 읽는다.','Get advice on choosing research topics and working with scientific colleagues.','https://www.hachettebookgroup.com/titles/p-b-medawar/advice-to-a-young-scientist/9780465000920/',20),
('scientist','become','a900475d-bbd8-4ab0-b12b-5f5ffb6e4a75','연구 질문을 세우고 자료와 논증으로 답을 만드는 기본기를 배운다.','Learn to turn a research question into an evidence-based argument.','https://press.uchicago.edu/ucp/books/book/chicago/C/bo215874008',21),
('scientist','about','4ba7088f-2dbd-4835-b8d0-2c03e938a858','DNA 구조 발견의 경쟁과 협력을 당사자의 시선에서 읽는다.','Read a participant’s account of rivalry and collaboration in discovering DNA’s structure.','https://www.simonandschuster.com/books/The-Double-Helix/James-D-Watson/9780743216302',22),
('scientist','about','15e81fbe-ada3-425a-9c46-4b721133ee40','실험실을 꾸리고 연구를 이어가는 과학자의 노동과 삶을 들여다본다.','Explore the work and life of a scientist building a laboratory and sustaining research.','https://www.penguinrandomhouse.com/books/248239/lab-girl-by-hope-jahren/9781101873724/',23),
('humanities_scholar','become','7c6751a6-1e2c-4a16-a081-23e37be0554d','텍스트의 논지를 파악하고 서로 다른 책을 비교하며 읽는 방법을 배운다.','Learn to identify arguments and compare texts through analytical reading.','https://www.simonandschuster.com/books/How-to-Read-a-Book/Mortimer-J-Adler/9780671212094',24),
('humanities_scholar','become','a900475d-bbd8-4ab0-b12b-5f5ffb6e4a75','읽은 자료를 연구 질문과 설득력 있는 학술적 논증으로 연결한다.','Connect your reading with research questions and persuasive scholarly arguments.','https://press.uchicago.edu/ucp/books/book/chicago/C/bo215874008',25),
('humanities_scholar','about','7f3f79a0-01e2-4cb0-9f7d-6c0c3cc6df36','역사학자가 사료를 읽고 과거를 이해하는 일이 무엇인지 살펴본다.','Explore what historians do when examining sources and interpreting the past.','https://manchesteruniversitypress.co.uk/9780719032929/',26),
('humanities_scholar','about','e3942652-9a5a-4987-90ff-97b636603ab5','지식인이 권력과 사회 앞에서 맡는 역할과 책임을 생각한다.','Consider an intellectual’s role and responsibilities in relation to power and society.','https://www.penguinrandomhouse.com/books/159790/representations-of-the-intellectual-by-edward-w-said/',27),
('social_scientist','become','a900475d-bbd8-4ab0-b12b-5f5ffb6e4a75','사회 현상에 관한 질문을 자료·근거·논증으로 검토하는 방법을 배운다.','Learn to investigate social questions with sources, evidence and arguments.','https://press.uchicago.edu/ucp/books/book/chicago/C/bo215874008',28),
('social_scientist','become','73fa3ee5-7f71-4739-93e6-8a0fdbbc9493','개인의 경험을 사회 구조와 연결해 연구 문제를 만드는 시각을 익힌다.','Learn to connect individual experience with social structures when framing research.','https://openlibrary.org/isbn/9780195133738',29),
('social_scientist','about','3625eafd-9436-4d1d-8f36-76d2108dc473','당연해 보이는 일상을 낯설게 보는 사회학자의 시선을 소개한다.','Discover the sociologist’s way of questioning seemingly ordinary social life.','https://www.penguinrandomhouse.com/books/12385/invitation-to-sociology-by-peter-l-berger/',30),
('social_scientist','about','7f95754f-9143-4088-9779-a0a04e655069','개인적 사건을 사회적 현상으로 분석하는 사회과학 연구의 고전을 읽는다.','Read a classic example of analyzing an individual act as a social phenomenon.','https://www.routledge.com/Suicide-A-Study-in-Sociology/Durkheim/p/book/9780415278317',31),
('director','become','4b42e7a2-06a1-4ba9-9259-e2b80672e1c9','각본 선택부터 배우·촬영·편집까지 감독이 하는 구체적인 일을 배운다.','Learn a director’s practical work from choosing a script to acting, shooting and editing.','https://www.penguinrandomhouse.com/books/104488/making-movies-by-sidney-lumet/9780679756606/',32),
('director','become','39efe8cb-9db4-49b1-90c5-38b3d316f868','장면을 샷과 동선으로 나누어 시각적으로 설계하는 방법을 익힌다.','Learn to plan scenes visually through shots, staging and movement.','https://mwp.com/product/film-directing-shot-shot-25th-anniversary-edition-visualizing-concept-screen/',33),
('director','about','9e9c7155-4a99-549d-bad3-cc95038f70d6','두 감독의 대화를 통해 영화의 선택 뒤에 놓인 생각을 들여다본다.','See the thinking behind cinematic choices through a conversation between two directors.','https://www.simonandschuster.com/books/Hitchcock/Francois-Truffaut/9780671604295',34),
('director','about','f3d98f6c-d8a0-5af6-bc0f-1d535e1442a2','베리만의 자서전으로 한 감독의 삶과 예술적 기억을 읽는다.','Read a director’s life and artistic memories through Bergman’s autobiography.','https://press.uchicago.edu/ucp/books/book/chicago/M/bo5430622.html',35),
('musician','become','c83eec17-290b-4143-8d66-c9c23a752874','작사와 작곡을 작은 연습으로 나누어 첫 곡을 완성하는 방법을 배운다.','Learn to finish your first song through manageable exercises in lyrics and composition.','https://www.penguinrandomhouse.com/books/670253/how-to-write-one-song-by-jeff-tweedy/',36),
('musician','become','28e60455-5140-44ef-b792-3c271cf7d6eb','관현악 작곡·편곡을 위해 악기의 특성과 소리의 조합을 배운다.','Study instrumental characteristics and combinations for orchestral composition and arranging.','https://wwnorton.co.uk/books/9780393283730-the-study-of-orchestration-0675df45-d3d3-415e-9e42-9c331b5c46c7',37),
('musician','about','f3838f7a-4a2a-456e-bb62-bae881791ae7','음악이 인간의 뇌와 삶에 미치는 영향을 다양한 사례로 읽는다.','Explore music’s effects on the brain and human life through case histories.','https://www.penguinrandomhouse.com/the-read-down/books-to-read-if-you-love-music',38),
('musician','about','44af4d29-6af5-40ca-916a-e0cbffd8cca0','지휘자의 경험과 해석을 대화로 읽으며 연주와 음악가의 일을 들여다본다.','Explore performance and a musician’s work through a conductor’s experiences and interpretations.','https://www.penguinrandomhouse.com/books/242969/absolutely-on-music-by-haruki-murakami-with-seiji-ozawa/',39),
('visual_artist','become','a5a3d061-26cc-46c4-8097-737e5436dc42','대상을 관찰하고 선·비례·명암으로 옮기는 드로잉 연습을 시작한다.','Start practicing observation, line, proportion and shading in drawing.','https://www.penguinrandomhouse.com/books/310367/drawing-on-the-right-side-of-the-brain-by-betty-edwards/',40),
('visual_artist','become','729e9e82-6fc6-40bc-8f75-7f60a9985703','색이 주변 색과 만나 다르게 보이는 현상을 실험하며 배운다.','Learn through experiments in how surrounding colors change color perception.','https://yalebooks.yale.edu/book/9780300146936/interaction-of-color/',41),
('visual_artist','about','dcfafdf5-56ad-4925-9fde-9074f8736867','시대마다 미술가들이 무엇을 표현하려 했는지 작품과 함께 읽는다.','Read how artists in different periods approached expression through their works.','https://www.phaidon.com/en-ca/products/the-story-of-art-16th-edition',42),
('visual_artist','about','aed6c25e-8e66-4087-8274-20710a2a454f','그림과 이미지를 보는 방식에 사회와 권력이 어떻게 작용하는지 살펴본다.','Explore how society and power influence the way we look at art and images.','https://www.penguinrandomhouse.com/books/324430/ways-of-seeing-by-john-berger/',43),
('author','become','21b81f26-a17f-44ec-b11b-cd6ee4227c77','어휘·문장·초고·퇴고를 다루며 소설을 쓰는 기본기를 배운다.','Learn a fiction writer’s tools for language, drafting and revision.','https://www.simonandschuster.com/books/On-Writing/Stephen-King/9781982159375',44),
('author','become','147bdfb0-0fc6-45ef-802a-1e6ac205ef08','완벽한 첫 문장을 기다리지 않고 작은 단위로 초고를 쓰는 법을 익힌다.','Learn to write in manageable steps instead of waiting for a perfect first draft.','https://www.penguinrandomhouse.com/books/97395/bird-by-bird-by-anne-lamott/9780385480017/',45),
