BEGIN;
CREATE TABLE public.celeb_professions (
  value text PRIMARY KEY CHECK (value ~ '^[a-z][a-z0-9_]*$' AND value NOT IN ('all','uncategorized')),
  label text NOT NULL CHECK (btrim(label) <> ''),
  label_en text NOT NULL CHECK (btrim(label_en) <> ''),
  description text NOT NULL DEFAULT '',
  description_en text NOT NULL DEFAULT '',
  sort_order integer NOT NULL DEFAULT 0
);
CREATE TABLE public.profession_book_picks (
  profession text NOT NULL REFERENCES public.celeb_professions(value) ON UPDATE CASCADE,
  category text NOT NULL CHECK (category IN ('become','about')),
  content_id text NOT NULL REFERENCES public.contents(id),
  note text NOT NULL CHECK (btrim(note) <> ''),
  note_en text NOT NULL CHECK (btrim(note_en) <> ''),
  source_url text NOT NULL CHECK (source_url ~ '^https://'),
  sort_order integer NOT NULL DEFAULT 0,
  PRIMARY KEY (profession, category, content_id)
);
ALTER TABLE public.celeb_professions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profession_book_picks ENABLE ROW LEVEL SECURITY;
CREATE POLICY professions_read ON public.celeb_professions FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY profession_books_read ON public.profession_book_picks FOR SELECT TO anon, authenticated USING (true);
GRANT SELECT ON public.celeb_professions, public.profession_book_picks TO anon, authenticated;
GRANT ALL ON public.celeb_professions, public.profession_book_picks TO service_role;
ALTER TABLE public.celebs DROP CONSTRAINT celebs_profession_check;
ALTER TABLE public.celebs ADD CONSTRAINT celebs_profession_fkey FOREIGN KEY (profession) REFERENCES public.celeb_professions(value) ON UPDATE CASCADE;
CREATE FUNCTION public.invalidate_profession_catalog() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $fn$
BEGIN
  PERFORM public.web_revalidate_send(ARRAY['celebs','contents']);
  RETURN NULL;
END;
$fn$;
REVOKE ALL ON FUNCTION public.invalidate_profession_catalog() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER profession_catalog_changed AFTER INSERT OR UPDATE OR DELETE ON public.celeb_professions FOR EACH STATEMENT EXECUTE FUNCTION public.invalidate_profession_catalog();
CREATE TRIGGER profession_books_changed AFTER INSERT OR UPDATE OR DELETE ON public.profession_book_picks FOR EACH STATEMENT EXECUTE FUNCTION public.invalidate_profession_catalog();
NOTIFY pgrst, 'reload schema';
COMMIT;
